import 'package:mad_flutter_practicum/domain/domain.dart';

import 'currency_list/widgets/currency_card.dart';
import 'news_list/widgets/news_card.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<void> _initFuture;

  List<CurrencyModel>? _currencies;
  List<NewsModel>? _news;

  @override
  void initState() {
    super.initState();
    _initFuture = _loadData();
  }

  Future<void> _loadData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    try {
      final results = await Future.wait(<Future<dynamic>>[
        currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20)),
        newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
      ]);

      if (!mounted) return;

      setState(() {
        _currencies = (results[0] as CurrencyPage).items;
        _news = results[1] as List<NewsModel>;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() {});
    }
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<void>(
        future: _initFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting && _currencies == null && _news == null) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<Widget> sections = <Widget>[];

          if (_currencies != null && _currencies!.isNotEmpty) {
            sections.add(
              Padding(
                padding: const EdgeInsets.fromLTRB(22, 16, 22, 8),
                child: Text(loc.dashboardCurrencyRates, style: context.fonts.semiBold12),
              ),
            );
            sections.add(
              SizedBox(
                height: 90,
                child: ListView.builder(
                  scrollDirection: Axis.horizontal,
                  itemCount: _currencies!.length,
                  itemBuilder: (BuildContext context, int index) {
                    final CurrencyModel currency = _currencies![index];
                    return Padding(
                      padding: const EdgeInsets.only(right: 8),
                      child: SizedBox(
                        width: 200,
                        child: CurrencyCard(model: currency),
                      ),
                    );
                  },
                ),
              ),
            );
          }

          if (_news != null && _news!.isNotEmpty) {
            sections.add(const Divider(height: 24));
            sections.add(
              Padding(
                padding: const EdgeInsets.fromLTRB(22, 8, 22, 8),
                child: Text(loc.dashboardNews, style: context.fonts.semiBold12),
              ),
            );
            sections.add(
              Expanded(
                child: ListView.builder(
                  itemCount: _news!.length,
                  padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  itemBuilder: (BuildContext context, int index) {
                    final NewsModel news = _news![index];
                    return Padding(
                      key: ValueKey(news.link),
                      padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                      child: NewsCard(model: news),
                    );
                  },
                ),
              ),
            );
          }

          if (sections.isEmpty) {
            return const Center(child: Text('No data'));
          }

          return Column(children: sections);
        },
      ),
    );
  }
}
