import 'package:flutter_test/flutter_test.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

void main() {
  group('HomePage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();
    final MockSettingsRepository mockSettingsRepository = MockSettingsRepository();

    late Widget homeWidget;

    setUp(() {
      homeWidget = buildWidget(
        providers: [
          Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          Provider<NewsRepository>.value(value: mockNewsRepository),
          Provider<SettingsRepository>.value(value: mockSettingsRepository),
        ],
        child: const HomePage(),
      );

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => const CurrencyPage(items: [], page: 0, hasMore: false));
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => <NewsModel>[]);
      when(mockSettingsRepository.readThemeMode()).thenReturn(AppThemeMode.system);
    });

    testWidgets('should display all navigation tabs with correct labels', (WidgetTester tester) async {
      await tester.pumpWidget(homeWidget);
      await tester.pumpAndSettle();

      // Check that the BottomNavigationBar exists and has 4 items
      final Finder bottomNav = find.byType(BottomNavigationBar);
      expect(bottomNav, findsOneWidget);

      // Verify HomePage is displayed (which contains all navigation)
      expect(find.byType(HomePage), findsOneWidget);
    });

    testWidgets('should navigate to correct pages when tabs are tapped', (WidgetTester tester) async {
      await tester.pumpWidget(homeWidget);
      await tester.pumpAndSettle();

      // Initial state shows DashboardPage at index 0
      expect(find.byType(DashboardPage), findsOneWidget);

      // Navigate using BottomNavigationBar's onTap callback via tab indices
      final Finder bottomNav = find.byType(BottomNavigationBar);

      // Tap each tab by finding Icon widgets inside the navigation bar
      // Tab 0 (Dashboard) - already showing, has TabWidget with Image.asset
      expect(find.byType(DashboardPage), findsOneWidget);

      // Tab 1 (CurrencyListPage) - tap on the second BottomNavigationBarItem
      // Use gesture to tap at position within bottom nav bar
      final Rect navRect = tester.getRect(bottomNav);
      final double tabWidth = navRect.width / 4.0;

      // Tap at center of each tab section (offset from left edge)
      await tester.tapAt(Offset(navRect.left + tabWidth * 0.5, navRect.center.dy));
      await tester.pumpAndSettle();

      // Should be on DashboardPage still (index 0)
      expect(find.byType(DashboardPage), findsOneWidget);

      // Tap second tab position for CurrencyListPage  
      await tester.tapAt(Offset(navRect.left + tabWidth * 1.5, navRect.center.dy));
      await tester.pumpAndSettle();
      expect(find.byType(CurrencyListPage), findsOneWidget);

      // Tap third tab position for NewsListPage
      await tester.tapAt(Offset(navRect.left + tabWidth * 2.5, navRect.center.dy));
      await tester.pumpAndSettle();
      expect(find.byType(NewsListPage), findsOneWidget);

      // Tap fourth tab position for ProfilePage
      await tester.tapAt(Offset(navRect.left + tabWidth * 3.5, navRect.center.dy));
      await tester.pumpAndSettle();
      expect(find.byType(ProfilePage), findsOneWidget);

      // Back to first tab (Dashboard)
      await tester.tapAt(Offset(navRect.left + tabWidth * 0.5, navRect.center.dy));
      await tester.pumpAndSettle();
      expect(find.byType(DashboardPage), findsOneWidget);
    });
  });
}
